{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"RSO allowable rent increase and surcharges","requirement":"Landlords may raise rent once every 12 months by the LAHD allowable percentage. From February 2, 2026 no extra utility percentage increase and no 10% dependent increase are allowed; a 10% additional-tenant increase is. Registration, code-enforcement and smoke-detector surcharges may be passed through.","key_value":"once every 12 months at the allowable rent increase percentage","coverage_conditions":"Rental properties in the City of Los Angeles first built on or before October 1, 1978, including replacement units under LAMC Section 151.28.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":"Rent amount not regulated for condominium or townhome tenancies commenced after December 31, 1995.","coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28 and if any of the following:"]},"exemptions":"Units approved under the Luxury Exemption (monthly rent charged on or before May 31, 1978) and units holding temporary exemptions.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Rent Stabilization Ordinance (L.A.M.C. §151.00 et seq.)","quoted_span":"Rent may be increased once every 12 months by the allowable rent increase percentage (click here to view the allowable rent increase PDF ). Effective February 2, 2026, the landlord can no longer include an additional percentage increase for utilities.","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D041-01","doc_id":"D041","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"RSO legal reasons for eviction and relocation assistance","requirement":"A landlord may terminate an RSO tenancy only for the listed at-fault or no-fault reasons; no-fault evictions require payment of tenant relocation assistance, and termination notices must be filed with LAHD within three business days of service.","key_value":"3 business days to file notice","coverage_conditions":"All rental units subject to the City of Los Angeles Rent Stabilization Ordinance (RSO) — properties first built on or before October 1, 1978.","applicability":{"conditions":[{"type":"built","role":"covered","op":"on_or_before","date":"1978-10-01","basis":"construction"}],"per_tenancy":null,"coverage_quotes":["Generally, the RSO applies to rental properties that were first built on or before October 1, 1978, as well as replacement units under LAMC Section 151.28 and if any of the following:"]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"L.A.M.C. § 151.09","quoted_span":"All notices to terminate a tenancy for all rental units subject to City’s Rent Stabilization Ordinance (RSO) must be filed with the Los Angeles Housing Department (LAHD) within three (3) business days of service on the tenant","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
